package com.universalplatform.content;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="learning_resource")
class LearningResource { @Id UUID id; @Column(nullable=false) UUID tenantId; @Column(nullable=false) UUID stableKey; @Column(nullable=false) String title; @Column(length=4000) String description; @Enumerated(EnumType.STRING) @Column(nullable=false) ResourceKind resourceKind; UUID courseId; UUID moduleId; UUID classSessionId; String language; @Enumerated(EnumType.STRING) @Column(nullable=false) ResourceVisibility visibility; @Enumerated(EnumType.STRING) @Column(nullable=false) DownloadPolicy downloadPolicy; Instant releaseAt; Instant expiresAt; @Column(nullable=false) int currentVersion; @Column(nullable=false) String createdBy; @Column(nullable=false) Instant createdAt; @Column(nullable=false) Instant updatedAt; @Version @Column(name="row_version") long version;
 protected LearningResource(){} LearningResource(UUID id,UUID tenantId,String actor,String title,String description,ResourceKind kind,UUID courseId,UUID moduleId,UUID classSessionId,String language,ResourceVisibility visibility,DownloadPolicy downloadPolicy,Instant releaseAt,Instant expiresAt,Instant now){this.id=id;this.tenantId=tenantId;this.stableKey=UUID.randomUUID();this.createdBy=actor;this.title=title;this.description=description;this.resourceKind=kind;this.courseId=courseId;this.moduleId=moduleId;this.classSessionId=classSessionId;this.language=language;this.visibility=visibility;this.downloadPolicy=downloadPolicy;this.releaseAt=releaseAt;this.expiresAt=expiresAt;this.currentVersion=1;this.createdAt=now;this.updatedAt=now;}
 void nextVersion(Instant now){currentVersion++;updatedAt=now;}
}
